#!/usr/bin/env bash
# DrugEx PBS executor — exactly one run per job.
#
# Do not edit this file to start a run. `submit.py` stages the release, writes a
# JSON spec and calls:
#     qsub -N <name> -q <queue> -l select=… -v RUN_SPEC=…,STORAGE_DIR=… <this file>
# The #PBS lines below are only the fallback defaults for a hand-run `qsub`.
#PBS -N drugex_run
#PBS -l select=1:ncpus=16:mem=32gb:scratch_local=15gb:spec=8.0
#PBS -l walltime=24:00:00
#PBS -j oe

set -euo pipefail
: "${PBS_JOBID:?Run this as a PBS job}"
: "${SCRATCHDIR:?PBS scratch allocation is required}"
: "${STORAGE_DIR:?Set STORAGE_DIR (submit.py does this)}"
: "${RUN_SPEC:?Set RUN_SPEC (submit.py does this)}"

# The validated environment lives on storage and survives every code sync.
PYTHON="$STORAGE_DIR/.venv/bin/python"
test -x "$PYTHON" || { echo "Missing validated environment: $PYTHON" >&2; exit 1; }

read_spec() {
    "$PYTHON" -c 'import json,sys; print(json.load(open(sys.argv[1]))[sys.argv[2]])' \
        "$RUN_SPEC" "$1"
}
EXP_NAME=$(read_spec name)
SOURCE_DIR=$(read_spec source)
DRUGEX_SOURCE_REVISION=$(read_spec revision)
export DRUGEX_SOURCE_REVISION

test -f "$SOURCE_DIR/_david/code/pipeline.py" ||
    { echo "Release is incomplete or gone: $SOURCE_DIR" >&2; exit 1; }

# One directory per run, named like the local default: YYYYmmdd_HHMM_<name>.
# A same-minute collision gets _2, _3 … so two runs never share a manifest.
RUN_ID="$(date +%Y%m%d_%H%M)_${EXP_NAME}"
RESULTS_DIR="$STORAGE_DIR/_david/output/$RUN_ID"
suffix=2
while [[ -e "$RESULTS_DIR" ]]; do
    RESULTS_DIR="$STORAGE_DIR/_david/output/${RUN_ID}_${suffix}"
    suffix=$((suffix + 1))
done
RUN_ID="$(basename "$RESULTS_DIR")"
OUT_DIR="$SCRATCHDIR/output/$RUN_ID"

# PBS sets NCPUS inconsistently (1 for a 4-core job); the node file is the contract.
JOB_CPUS="${NCPUS:-}"
if [[ -n "${PBS_NODEFILE:-}" && -r "${PBS_NODEFILE:-}" ]]; then
    JOB_CPUS=$(wc -l < "$PBS_NODEFILE")
fi

cat <<HEADER
================ DrugEx job ================
job        : $PBS_JOBID
name       : $EXP_NAME
node       : $(hostname)
queue      : ${PBS_QUEUE:-unknown}
cpus       : ${JOB_CPUS:-?}
scratch    : $SCRATCHDIR
release    : $SOURCE_DIR
revision   : $DRUGEX_SOURCE_REVISION
run id     : $RUN_ID
results    : $RESULTS_DIR
============================================
HEADER

cleanup() {
    # Runs on success, failure, SIGTERM (walltime) and SIGINT, so partial results
    # are always copied back instead of dying with the scratch allocation.
    local status=$?
    trap - EXIT
    if [[ -d "$OUT_DIR" ]]; then
        if ! mkdir -p "$RESULTS_DIR" || ! rsync -a "$OUT_DIR/" "$RESULTS_DIR/"; then
            echo "Result transfer FAILED; scratch kept at $SCRATCHDIR" >&2
            exit 1
        fi
        echo "Results copied to $RESULTS_DIR (exit status $status)"
    fi
    if command -v clean_scratch >/dev/null 2>&1; then
        clean_scratch
    else
        rm -rf "${SCRATCHDIR:?}"/*
    fi
    exit "$status"
}
trap cleanup EXIT
trap 'exit 143' TERM
trap 'exit 130' INT

mkdir -p "$OUT_DIR" "$SCRATCHDIR/DrugEx"
rsync -a "$SOURCE_DIR/" "$SCRATCHDIR/DrugEx/"
cd "$SCRATCHDIR/DrugEx"
cp "$RUN_SPEC" "$OUT_DIR/submission.json"

export MPLBACKEND=Agg
export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
export DRUGEX_MP_CONTEXT=forkserver
export PYTHONPATH="$SCRATCHDIR/DrugEx:${PYTHONPATH:-}"

# Arguments are a JSON array, never an eval'd string: quoting survives.
"$PYTHON" - "$RUN_SPEC" "$OUT_DIR" <<'PY' 2>&1 | tee "$OUT_DIR/execution.log"
import json
import subprocess
import sys

with open(sys.argv[1]) as handle:
    spec = json.load(handle)
subprocess.run(
    [sys.executable, "-u", "-m", "_david.code.pipeline",
     "--output-dir", sys.argv[2], *spec["args"]],
    check=True,
)
PY

echo "Pipeline finished for $RUN_ID"
